//! 🧪️ Actual neutral sessions retain their draft bytes, reports and unused original backing until admitted release.
use crate::{TimeTravelSession,TimeTravelBase,TimeTravelStage,TimeTravelDraft,TimeTravelTarget,TimeTravelPending,TimeTravelProgress};
use semio_framework_value::{retirement::controlled::ControlledRetirement,retained_clone::{RetainedCloneGrant,RetainedCloneStep},ValueRefusalKind};
use semio_framework_trace::observe_heap_allocations_on_this_thread;
fn original_native_grant()->RetainedCloneGrant{let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let policy=&law["originalRetirementGrant"];RetainedCloneGrant{maximum_items:policy["items"].as_u64().unwrap()as usize,maximum_copy_bytes:policy["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:policy["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:policy["release"].as_u64().unwrap()as usize,maximum_depth:policy["depth"].as_u64().unwrap()as usize}}
fn original_discard_demand(owner:&crate::TimeTravelDiscardCursor,session:&TimeTravelSession,body:usize)->Result<semio_framework_value::RetirementDemand,semio_framework_value::ValueError>{if owner.is_validating(){Ok(owner.validation_demands(session))}else if owner.prepared_stage().is_some(){owner.commit_demands(session)}else{owner.retirement_demands(body)}}
fn text(value:&str,capacity:usize)->String{let mut original=String::with_capacity(capacity);original.push_str(value);original}
fn input(capacity:usize)->protocol::InputReplacement{let mut payload=Vec::with_capacity(capacity);payload.extend_from_slice(&[0,34,255]);protocol::InputReplacement::Input{schema:text("native.v1",capacity),payload}}
fn target(capacity:usize)->TimeTravelTarget{TimeTravelTarget{mutation:protocol::MutationId(text("node.α\0😀",capacity)),position:0}}
fn drafts(capacity:usize,original_grant:RetainedCloneGrant)->semio_framework_value::list::PagedList<TimeTravelDraft,{usize::MAX}>{
 let mut owner=semio_framework_value::list::PagedList::default();if capacity>0{while owner.capacity()<8192{assert!(owner.reserve_exact_capacity_one(8192,original_grant.maximum_capacity_bytes).unwrap().progressed)}}owner
}
#[test]
fn time_travel_session_retirement_original_drafts_reports_and_empty_capacities(){
 let original_grant=original_native_grant();
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 for cap in fixture["capacities"].as_array().unwrap(){let capacity=cap.as_u64().unwrap()as usize;for copy in fixture["copyGrants"].as_array().unwrap(){let copy=copy.as_u64().unwrap()as usize;for cut in fixture["cancelCuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;
  let(original,heap)=observe_heap_allocations_on_this_thread(||{
   let mut accepted=drafts(capacity,original_grant);accepted.push(TimeTravelDraft{target:target(capacity),replacement:input(capacity)});
   let pending=Some(TimeTravelPending{target:target(capacity),original:input(capacity),replacement:protocol::InputReplacement::Withdrawn,return_stage:TimeTravelStage::Reviewing});
   let mut messages=Vec::with_capacity(if capacity==0{0}else{8192});let mut ids=Vec::with_capacity(if capacity==0{0}else{8192});ids.push(text("",capacity));messages.push(protocol::MutationMessage{level:semio_framework_diagnostic::Severity::Error,code:text("mutation.target-missing",capacity).into(),message:text("node \"α\0😀\" not found",capacity),target:ids,op_index:Some(0)});
   let mut outcomes=Vec::with_capacity(if capacity==0{0}else{8192});outcomes.push(protocol::MutationReplayOutcome{mutation_id:protocol::MutationId(text("node.α\0😀",capacity)),edit_id:text("edit.α",capacity),op_index:0,worst:Some(semio_framework_diagnostic::Severity::Error),messages,superseded:false,withdrawn:false});
   TimeTravelSession{id:1,generation:3,base:TimeTravelBase::default(),stage:TimeTravelStage::Reviewing,accepted,pending,report:Some(protocol::ReplayReport{from_position:0,outcomes,worst:Some(semio_framework_diagnostic::Severity::Error)}),progress:Some(TimeTravelProgress{done:1,total:2}),fault:Some(text("timeTravel.cancelled",capacity))}
  });assert_eq!(heap.released_bytes,0);let held=heap.requested_bytes;
  let target=semio_framework_value::ToValue::to_value(&original.accepted[0].target.mutation);assert_eq!(serde_json::to_value(target).unwrap(),fixture["wire"]["accepted"][0]["target"]["mutation"]);let payload=semio_framework_value::ToValue::to_value(&original.accepted[0].replacement);assert_eq!(serde_json::to_value(payload).unwrap(),fixture["wire"]["accepted"][0]["replacement"]);assert_eq!(original.fault.as_deref(),Some("timeTravel.cancelled"));assert_eq!(original.report.as_ref().unwrap().outcomes[0].messages[0].target[0],"");assert_eq!(serde_json::to_value(semio_framework_value::ToValue::to_value(original.report.as_ref().unwrap())).unwrap(),fixture["wire"]["report"]);
  let(mut owner,heap)=observe_heap_allocations_on_this_thread(||ControlledRetirement::new(original).unwrap_or_else(|_|panic!("declared original neutral session")));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut births=0;let mut releases=0;let mut turns=0;
  while !owner.terminal_is_empty(){let((work,capacity,release,depth),heap)=observe_heap_allocations_on_this_thread(||(owner.next_copy_byte_demand().unwrap(),owner.next_capacity_byte_demand(original_grant.maximum_copy_bytes).unwrap(),owner.next_release_byte_demand().unwrap(),owner.next_depth_demand().unwrap()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let grant=original_grant;
   for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(work>0).then_some(RetainedCloneGrant{maximum_copy_bytes:work.saturating_sub(1),..grant}),(capacity>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:capacity.saturating_sub(1),..grant}),(release>0).then_some(RetainedCloneGrant{maximum_release_bytes:release.saturating_sub(1),..grant}),(depth>0).then_some(RetainedCloneGrant{maximum_depth:depth.saturating_sub(1),..grant})].into_iter().flatten(){let(result,heap)=observe_heap_allocations_on_this_thread(||owner.step(denied));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));match result{Ok(step)=>assert_eq!(step.progress(),Default::default()),Err(error)=>assert_eq!(error.kind,ValueRefusalKind::DepthLimit)}}
   let(step,heap)=observe_heap_allocations_on_this_thread(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=heap.requested_bytes;releases+=heap.released_bytes;turns+=1;if turns==cut{let(same,heap)=observe_heap_allocations_on_this_thread(||owner);owner=same;assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}assert!(turns<100000);assert!(step.progress().copied_items>0||matches!(step,RetainedCloneStep::Complete(_)));
  }
  assert_eq!(releases,held+births);let(_,heap)=observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] Original TimeTravel session capacity={} copy={copy} cancel={cut} turns={turns} original={held} births={births} released={releases} terminalDrop=0",cap);
 }}}
}

#[test]
fn time_travel_event_retirement_original_pending_commands(){
 use crate::{TimeTravelEvent as E,TimeTravelChoice};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🧫️lifecycle-law/🔣️.json")).unwrap();
 for capacity in [0,8192,65536]{for body in [1,17,4096]{for cut in [0,3]{for(key,value)in fixture["events"].as_object().unwrap(){
  let(original,heap)=observe_heap_allocations_on_this_thread(||{let mut original=super::super::tests::event(value);match &mut original{
   E::Begin{target,original}|E::BeginWithdrawn{target,original}=>{grow_text(&mut target.mutation.0,capacity);grow_input(original,capacity)},
   E::Draft{replacement,..}=>grow_input(replacement,capacity),E::Restore{target,..}=>grow_text(&mut target.0,capacity),
   E::ReplayCompleted{report,..}=>{for outcome in &mut report.outcomes{grow_text(&mut outcome.mutation_id.0,capacity);grow_text(&mut outcome.edit_id,capacity);for message in &mut outcome.messages{grow_text(&mut message.message,capacity);for target in &mut message.target{grow_text(target,capacity)}}}grow_vec(&mut report.outcomes,capacity)},
   E::ReplayFaulted{code,..}|E::FinalizeFaulted{code,..}=>grow_text(code,capacity),E::Choose{choice:TimeTravelChoice::Alternative{name},..}=>grow_text(name,capacity),
   E::BaseMoved{positions,..}=>{for target in positions.iter_mut(){grow_text(&mut target.mutation.0,capacity)}grow_vec(positions,capacity)},_=>{}
  }original});let held=heap.requested_bytes.checked_sub(heap.released_bytes).unwrap();assert_eq!(original.key().as_str(),key);
  close_event_original(original,held,body,cut,key,capacity);
 }}}}
}
fn grow_text(value:&mut String,capacity:usize){let original=std::mem::take(value);let mut retained=String::with_capacity(capacity.max(original.len()));retained.push_str(&original);*value=retained}
fn grow_vec<T>(value:&mut Vec<T>,capacity:usize){let original=std::mem::take(value);let mut retained=Vec::with_capacity(if capacity==0{original.len()}else{8192usize.max(original.len())});retained.extend(original);*value=retained}
fn grow_input(value:&mut protocol::InputReplacement,capacity:usize){if let protocol::InputReplacement::Input{schema,payload}=value{grow_text(schema,capacity);grow_vec(payload,capacity)}}
/// 🎟️ Every pending native command keeps its original storage until independently funded release.
fn close_event_original<T:semio_framework_value::retirement::RetireOwned>(original:T,held:usize,body:usize,cut:usize,key:&str,capacity:usize){
 let original_grant=original_native_grant();
 let(mut owner,heap)=observe_heap_allocations_on_this_thread(||ControlledRetirement::new(original).unwrap_or_else(|_|panic!("declared pending command")));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut births=0;let mut releases=0;let mut turns=0;
 while !owner.terminal_is_empty(){let((copy,capacity,release,depth),heap)=observe_heap_allocations_on_this_thread(||(owner.next_copy_byte_demand().unwrap(),owner.next_capacity_byte_demand(original_grant.maximum_copy_bytes).unwrap(),owner.next_release_byte_demand().unwrap(),owner.next_depth_demand().unwrap()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let grant=original_grant;
  for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(copy>0).then_some(RetainedCloneGrant{maximum_copy_bytes:copy.saturating_sub(1),..grant}),(capacity>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:capacity.saturating_sub(1),..grant}),(release>0).then_some(RetainedCloneGrant{maximum_release_bytes:release.saturating_sub(1),..grant}),(depth>0).then_some(RetainedCloneGrant{maximum_depth:depth.saturating_sub(1),..grant})].into_iter().flatten(){let(step,heap)=observe_heap_allocations_on_this_thread(||owner.step(denied));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));match step{Ok(step)=>assert_eq!(step.progress(),Default::default()),Err(error)=>assert_eq!(error.kind,ValueRefusalKind::DepthLimit)}}
  let(step,heap)=observe_heap_allocations_on_this_thread(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=heap.requested_bytes;releases+=heap.released_bytes;turns+=1;if turns==cut{let(same,heap)=observe_heap_allocations_on_this_thread(||owner);owner=same;assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0))}assert!(turns<100000);assert!(step.progress().copied_items>0||matches!(step,RetainedCloneStep::Complete(_)));
 }assert_eq!(releases,held+births);let(_,heap)=observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] Original pending event={key} capacity={capacity} body={body} cancel={cut} original={held} births={births} released={releases} terminalDrop=0");
}

#[test]
fn time_travel_session_paged_accepted_original_growth_and_retirement(){
 let original_grant=original_native_grant();
 use semio_framework_value::list::PagedListEditCursor;
 for body in [1,17,4096]{
  let(mut session,heap)=observe_heap_allocations_on_this_thread(TimeTravelSession::default);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));session.stage=TimeTravelStage::Reviewing;let mut held=0;let mut largest=0;
  for index in 0..1025u32{
   let(draft,heap)=observe_heap_allocations_on_this_thread(||TimeTravelDraft{target:TimeTravelTarget{mutation:protocol::MutationId(format!("draft.{index}")),position:index},replacement:protocol::InputReplacement::Input{schema:"schema".into(),payload:vec![index as u8,0,255]}});held+=heap.requested_bytes-heap.released_bytes;let mut draft=Some(draft);
   while !session.accepted.has_reserved_slot(){
    let(demand,heap)=observe_heap_allocations_on_this_thread(||session.accepted.next_capacity_allocation_bytes(session.accepted.len()+1).unwrap().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(demand<=4096);let denied=demand.saturating_sub(1);let(step,heap)=observe_heap_allocations_on_this_thread(||session.accepted.reserve_one(denied).unwrap());assert!(!step.progressed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(step,heap)=observe_heap_allocations_on_this_thread(||session.accepted.reserve_one(4096).unwrap());assert!(step.progressed);assert_eq!((heap.requested_bytes,heap.released_bytes),(step.allocated_bytes,0));held+=heap.requested_bytes;largest=largest.max(heap.requested_bytes);
   }
   let mut insertion=PagedListEditCursor::insert(session.accepted.len(),session.accepted.len());let demand=std::mem::size_of::<TimeTravelDraft>();for(items,copy)in[(0,original_grant.maximum_copy_bytes),(1,demand.saturating_sub(1))]{let(step,heap)=observe_heap_allocations_on_this_thread(||insertion.step(&mut session.accepted,&mut draft,items,copy).unwrap());assert!(!step.complete);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(draft.is_some());}
   let(step,heap)=observe_heap_allocations_on_this_thread(||insertion.step(&mut session.accepted,&mut draft,1,original_grant.maximum_copy_bytes).unwrap());assert!(step.complete);assert!(draft.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(step.progress.placed_bytes,demand);
  }
  assert_eq!(session.accepted.len(),1025);for index in [0,512,1024]{assert_eq!(session.accepted[index].target.mutation.0,format!("draft.{index}"));assert_eq!(session.accepted[index].replacement,protocol::InputReplacement::Input{schema:"schema".into(),payload:vec![index as u8,0,255]});}
  assert_eq!(session.invariant_violation(),None);close_event_original(session,held,body,3,"accepted-native",0);eprintln!("[DEBUG] Actual Session accepted1025 native owners body={body} largestActualPage={largest} eachCapacity<=4096 zeroItemsAndCopyBelow=0 terminalDrop=0");
 }
}

#[test]
fn time_travel_discard_original_semantic_transition_and_residue(){
 let original_grant=original_native_grant();
 use crate::{TimeTravelDiscardCursor,TimeTravelEvent,TimeTravelRefusal};
 let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🧫️lifecycle-law/🔣️.json")).unwrap();let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["discardCases"].as_array().unwrap(){for capacity in [0,8192,65536]{for body in [1,17,4096]{for cut in [0,3]{
  let(mut session,heap)=observe_heap_allocations_on_this_thread(||{let mut session=super::super::tests::session(&law["contexts"][row["context"].as_str().unwrap()]);if let Some(pending)=session.pending.as_mut(){grow_text(&mut pending.target.mutation.0,capacity);grow_input(&mut pending.original,capacity);grow_input(&mut pending.replacement,capacity);}if session.accepted.is_empty()&&capacity>0{session.accepted=drafts(capacity,original_grant);}session});let held=heap.requested_bytes-heap.released_bytes;let pointer=session.pending.as_ref().map(|pending|pending.target.mutation.0.as_ptr());let before=session.clone();let mut event=Some(TimeTravelEvent::Discard{generation:row["generation"].as_u64().unwrap()as u32});
  for grant in [RetainedCloneGrant::default(),RetainedCloneGrant{maximum_items:1,maximum_depth:0,..Default::default()}]{let(result,heap)=observe_heap_allocations_on_this_thread(||TimeTravelDiscardCursor::admit_original(&mut event,grant).unwrap());assert!(result.is_none());assert!(event.is_some());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
  let((mut owner,receipt),heap)=observe_heap_allocations_on_this_thread(||TimeTravelDiscardCursor::admit_original(&mut event,original_grant).unwrap().unwrap());assert_eq!(receipt.copied_items,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(event.is_none());let mut births=0;let mut releases=0;let mut turns=0;let mut unsupported=false;
  while !owner.terminal_is_empty(){let(demand,heap)=observe_heap_allocations_on_this_thread(||original_discard_demand(&owner,&session,original_grant.maximum_copy_bytes).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let grant=original_grant;
   for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}),(demand.depth>0).then_some(RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant})].into_iter().flatten(){let(step,heap)=observe_heap_allocations_on_this_thread(||if owner.is_closing(){owner.close_step(denied)}else{drive_discard(&mut owner,&mut session,denied)});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(step.unwrap().progress(),Default::default());if turns==0{assert_eq!(session.pending.as_ref().map(|pending|pending.target.mutation.0.as_ptr()),pointer);}}
   let(step,heap)=observe_heap_allocations_on_this_thread(||if owner.is_closing(){owner.close_step(grant)}else{drive_discard(&mut owner,&mut session,grant)});assert_eq!(heap.requested_bytes,step.as_ref().map_or(0,|step|step.progress().retained_capacity_bytes));assert_eq!(heap.released_bytes,step.as_ref().map_or(0,|step|step.progress().released_bytes));births+=heap.requested_bytes;releases+=heap.released_bytes;turns+=1;assert!(turns<100000);
   match step{Ok(step)=>assert!(step.progress().fits(grant)),Err(error)=>{assert_eq!(error.kind,ValueRefusalKind::UnsupportedOwner);assert!(row["unsupported"].as_bool().unwrap_or(false));assert_eq!(session,before);unsupported=true;owner.begin_close();}}
   if cut>0&&turns==cut{owner.begin_close();}
  }
  if cut==0&&!unsupported{if let Some(rejection)=row["rejection"].as_str(){let expected=if rejection=="timeTravel.stale"{TimeTravelRefusal::Stale}else{TimeTravelRefusal::Illegal};assert_eq!(owner.result(),Some(Err(expected)));assert_eq!(session,before);}else{assert_eq!(owner.result(),Some(Ok(session.stage)));assert_eq!(session.stage.as_str(),row["stage"].as_str().unwrap());assert_eq!(session.generation,before.generation+u32::from(row["increment"].as_bool().unwrap()));assert!(session.pending.is_none());}}
  let(_,heap)=observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let remaining=held+births-releases;close_event_original(session,remaining,body,3,row["id"].as_str().unwrap(),capacity);eprintln!("[DEBUG] Actual native Discard case={} cap={capacity} body={body} cancel={cut} initial={held} cursorBirth={births} cursorRelease={releases} unsupported={unsupported} terminalDrop=0",row["id"].as_str().unwrap());
 }}}}
}

#[test]
fn time_travel_discard_completion_waits_for_original_retirement(){
 let original_grant=original_native_grant();
 use crate::{TimeTravelDiscardCursor,TimeTravelEvent};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🧫️lifecycle-law/🔣️.json")).unwrap();
 for context in ["editing.fromInactive.changed","editing.fromReviewing.changed"]{
  let(mut session,heap)=observe_heap_allocations_on_this_thread(||super::super::tests::session(&fixture["contexts"][context]));let held=heap.requested_bytes-heap.released_bytes;let mut event=Some(TimeTravelEvent::Discard{generation:session.generation});
  let(mut owner,_)=TimeTravelDiscardCursor::admit_original(&mut event,original_grant).unwrap().unwrap();let mut premature=false;let mut births=0;let mut releases=0;let mut turns=0;
  while !owner.terminal_is_empty(){premature|=owner.result().is_some();let demand=original_discard_demand(&owner,&session,original_grant.maximum_copy_bytes).unwrap();let grant=original_grant;let(step,heap)=observe_heap_allocations_on_this_thread(||drive_discard(&mut owner,&mut session,grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=heap.requested_bytes;releases+=heap.released_bytes;turns+=1;assert!(turns<100000);}
  assert_eq!(owner.result(),Some(Ok(session.stage)));let(_,heap)=observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));close_event_original(session,held+births-releases,17,3,context,0);assert!(!premature,"Discard acknowledged before original displaced owners were terminal");eprintln!("[DEBUG] Discard acknowledgement context={context} turns={turns} originalHeld={held} childBirth={births} childRelease={releases} terminalOnly=true");
 }
}

#[test]
fn time_travel_discard_validates_before_effect_admission_and_explicit_commit(){
 let original_grant=original_native_grant();
 use crate::{TimeTravelDiscardCursor,TimeTravelEvent};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🧫️lifecycle-law/🔣️.json")).unwrap();
 for context in ["editing.fromInactive.changed","editing.fromReviewing.changed"]{for body in [1,17,4096]{for cancel in [false,true]{
  let(mut session,heap)=observe_heap_allocations_on_this_thread(||{let mut session=super::super::tests::session(&fixture["contexts"][context]);let pending=session.pending.as_mut().unwrap();grow_text(&mut pending.target.mutation.0,65536);grow_input(&mut pending.original,65536);session});let held=heap.requested_bytes-heap.released_bytes;let before=session.clone();let pointer=session.pending.as_ref().unwrap().target.mutation.0.as_ptr();let mut event=Some(TimeTravelEvent::Discard{generation:session.generation});
  let(mut owner,_)=TimeTravelDiscardCursor::admit_original(&mut event,original_grant).unwrap().unwrap();let metadata=original_grant;let(error,heap)=observe_heap_allocations_on_this_thread(||owner.commit(&mut session,metadata).unwrap_err());assert_eq!(error.kind,ValueRefusalKind::WorkLimit);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(session,before);
  for denied in [RetainedCloneGrant{maximum_items:0,..metadata},RetainedCloneGrant{maximum_depth:0,..metadata}]{let(step,heap)=observe_heap_allocations_on_this_thread(||owner.validate(&session,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(owner.prepared_stage().is_none());}
  let(step,heap)=observe_heap_allocations_on_this_thread(||owner.validate(&session,metadata).unwrap());assert_eq!(step.progress().copied_items,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(session,before);let expected=if context.contains("Inactive"){TimeTravelStage::Inactive}else{TimeTravelStage::Reviewing};assert_eq!(owner.prepared_stage(),Some(expected));
  for _ in 0..16{let(step,heap)=observe_heap_allocations_on_this_thread(||owner.validate(&session,metadata).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(session.pending.as_ref().unwrap().target.mutation.0.as_ptr(),pointer);assert_eq!(session,before);assert!(owner.result().is_none());}
  if cancel{owner.begin_close();}else{let(step,heap)=observe_heap_allocations_on_this_thread(||owner.commit(&mut session,metadata).unwrap());assert_eq!(step.progress().copied_items,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(session.stage,expected);assert!(owner.result().is_none());}
  let mut births=0;let mut releases=0;let mut turns=0;while !owner.terminal_is_empty(){let demand=owner.retirement_demands(original_grant.maximum_copy_bytes).unwrap();let grant=original_grant;let(step,heap)=observe_heap_allocations_on_this_thread(||owner.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=heap.requested_bytes;releases+=heap.released_bytes;turns+=1;assert!(turns<100000);}
  if cancel{assert_eq!(session,before);assert_eq!(session.pending.as_ref().unwrap().target.mutation.0.as_ptr(),pointer);assert!(owner.result().is_none());}else{assert_eq!(owner.result(),Some(Ok(expected)));}
  let(_,heap)=observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));close_event_original(session,held+births-releases,body,3,context,65536);eprintln!("[DEBUG] Original Discard validation context={context} body={body} cancel={cancel} sixteenEffectAdmissionPauses=unchanged commit=explicit original={held} birth={births} release={releases} terminalDrop=0");
 }}}
}

#[test]
fn time_travel_pending_command_pays_slot_frame_and_original_transfer_separately(){
 use crate::{TimeTravelCommandCustody,TimeTravelEvent};use semio_framework_value::retirement::queue::RetirementQueue;
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let policy=&law["pendingCommandGrant"];let grant=RetainedCloneGrant{maximum_items:policy["items"].as_u64().unwrap()as usize,maximum_copy_bytes:policy["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:policy["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:policy["release"].as_u64().unwrap()as usize,maximum_depth:policy["depth"].as_u64().unwrap()as usize};
 let mut original=Some(TimeTravelEvent::Discard{generation:5});
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(value,heap)=observe_heap_allocations_on_this_thread(||TimeTravelCommandCustody::admit_original(&mut original,denied).unwrap());assert!(value.is_none());assert!(original.is_some());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
 let((mut command,receipt),heap)=observe_heap_allocations_on_this_thread(||TimeTravelCommandCustody::admit_original(&mut original,grant).unwrap().unwrap());assert_eq!(receipt.copied_items,1);assert_eq!(receipt.copied_bytes,TimeTravelCommandCustody::admission_copy_bytes());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(original.is_none());let mut queue=RetirementQueue::default();
 let(error,heap)=observe_heap_allocations_on_this_thread(||command.discard_admission_demand(&queue).unwrap_err());assert_eq!(error.kind,ValueRefusalKind::WorkLimit);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 let mut reserve=0;let mut births=0;let mut releases=0;while !queue.has_reserved_slot(){let demand=queue.next_reserve_capacity_byte_demand().unwrap();assert!(demand<=4096);let(receipt,heap)=observe_heap_allocations_on_this_thread(||queue.reserve_step(RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:demand.saturating_sub(1),maximum_depth:1,..Default::default()}).unwrap());assert_eq!(receipt,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(receipt,heap)=observe_heap_allocations_on_this_thread(||queue.reserve_step(grant).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,0));reserve+=heap.requested_bytes;births+=heap.requested_bytes;}
 let(demand,heap)=observe_heap_allocations_on_this_thread(||command.discard_admission_demand(&queue).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(demand.capacity_bytes<=4096);assert!(demand.capacity_bytes<=grant.maximum_capacity_bytes&&demand.depth<=grant.maximum_depth);
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(value,heap)=observe_heap_allocations_on_this_thread(||command.admit_discard(&queue,denied).unwrap());assert!(value.is_none());assert!(matches!(command.original(),Some(TimeTravelEvent::Discard{generation:5})));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
 let((frame,receipt),heap)=observe_heap_allocations_on_this_thread(||command.admit_discard(&queue,grant).unwrap().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,0));births+=heap.requested_bytes;assert!(command.original().is_none());let pointer=(&*frame)as *const _ as usize;
 let(receipt,heap)=observe_heap_allocations_on_this_thread(||queue.admit_retirement(frame,grant).unwrap_or_else(|_|panic!("paid original queue slot")));assert_eq!(receipt.copied_items,1);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 while !queue.terminal_is_empty(){let(step,heap)=observe_heap_allocations_on_this_thread(||queue.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=heap.requested_bytes;releases+=heap.released_bytes;}
 let(step,heap)=observe_heap_allocations_on_this_thread(||command.close_step(grant).unwrap());assert!(matches!(step,RetainedCloneStep::Complete(_)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(births,releases);let(_,heap)=observe_heap_allocations_on_this_thread(||{drop(command);drop(queue)});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] Pending command scalar original slot0heap reservedPage={reserve} separateFrame={} transferredPointer={pointer} birth={births} release={releases} terminalDrop=0",demand.capacity_bytes);
 for capacity in [8192,65536]{let(mut original,heap)=observe_heap_allocations_on_this_thread(||Some(TimeTravelEvent::Choose{generation:5,choice:crate::TimeTravelChoice::Alternative{name:text("α\0😀",capacity)}}));let held=heap.requested_bytes-heap.released_bytes;let(mut command,_)=TimeTravelCommandCustody::admit_original(&mut original,grant).unwrap().unwrap();let mut births=0;let mut releases=0;let mut turns=0;
  while !command.terminal_is_empty(){let demand=command.retirement_demands(grant.maximum_copy_bytes).unwrap();assert!(demand.copy_bytes<=grant.maximum_copy_bytes&&demand.capacity_bytes<=grant.maximum_capacity_bytes&&demand.release_bytes<=grant.maximum_release_bytes&&demand.depth<=grant.maximum_depth);let(step,heap)=observe_heap_allocations_on_this_thread(||command.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=heap.requested_bytes;releases+=heap.released_bytes;turns+=1;assert!(turns<100000);}
  assert_eq!(held+births,releases);let(_,heap)=observe_heap_allocations_on_this_thread(||drop(command));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] Pending owning original command cap={capacity} body=1 held={held} births={births} release={releases} cancellationTerminalDrop=0");
 }
}

fn drive_discard(owner:&mut crate::TimeTravelDiscardCursor,session:&mut TimeTravelSession,grant:RetainedCloneGrant)->Result<RetainedCloneStep,semio_framework_value::ValueError>{
 if owner.is_validating(){owner.validate(session,grant)}else if owner.prepared_stage().is_some(){owner.commit(session,grant)}else{owner.close_step(grant)}
}

#[test]
fn time_travel_discard_preparation_rejects_changed_prospective_stage(){
 let original_grant=original_native_grant();
 use crate::{TimeTravelDiscardCursor,TimeTravelEvent};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🧫️lifecycle-law/🔣️.json")).unwrap();let(mut session,heap)=observe_heap_allocations_on_this_thread(||super::super::tests::session(&fixture["contexts"]["editing.fromInactive.changed"]));let held=heap.requested_bytes-heap.released_bytes;let pointer=session.pending.as_ref().unwrap().target.mutation.0.as_ptr();let mut event=Some(TimeTravelEvent::Discard{generation:session.generation});let grant=original_grant;let(mut owner,_)=TimeTravelDiscardCursor::admit_original(&mut event,grant).unwrap().unwrap();owner.validate(&session,grant).unwrap();assert_eq!(owner.prepared_stage(),Some(TimeTravelStage::Inactive));session.pending.as_mut().unwrap().return_stage=TimeTravelStage::Reviewing;
 let(result,heap)=observe_heap_allocations_on_this_thread(||owner.commit(&mut session,grant));let denied=result.is_err();let inert=(heap.requested_bytes,heap.released_bytes)==(0,0);let unchanged=session.stage==TimeTravelStage::Editing&&session.pending.as_ref().is_some_and(|pending|pending.target.mutation.0.as_ptr()==pointer);let mut births=heap.requested_bytes;let mut release=heap.released_bytes;owner.begin_close();while !owner.terminal_is_empty(){let demand=owner.retirement_demands(17).unwrap();let(_,heap)=observe_heap_allocations_on_this_thread(||owner.close_step(grant).unwrap());births+=heap.requested_bytes;release+=heap.released_bytes;}let(_,heap)=observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));close_event_original(session,held+births-release,17,4,"prospective.stage.contention",0);assert!(denied,"changed original return stage invalidates prospective Store preparation");assert!(inert);assert!(unchanged);eprintln!("[DEBUG] Original Discard prospective Store stage contention retains same pending pointer, no Session transfer, no heap, cancellation terminalDrop0");
}
